// Package registry is the generation source of the IANA-derived TLS
// supported-group data (PQ-18): it loads the committed CSV snapshot under
// tests/fixtures/iana/ — regenerated by scripts/regen_tls_parameters.sh from
// https://www.iana.org/assignments/tls-parameters/tls-parameters-8.csv —
// into lookup form. The snapshot is versioned data, never hand-edited
// (AGENTS.md, registry rule): codepoint drift is fixed by regenerating,
// not by surveying.
package registry

import (
	"errors"
	"io"
)

// GroupEntry is one row of the IANA TLS Supported Groups table
// (tls-parameters-8.csv): codepoint, RFC-mandated name, transport
// applicability and IANA "Recommended" state.
type GroupEntry struct {
	Value       uint32
	Name        string
	DTLSOK      bool
	Recommended bool
	Reference   string
}

// errNotImplemented marks the PQ-18 stub commit; Load and Lookup land
// in the paired GREEN commit (ADR-0002 watched-RED pair).
var errNotImplemented = errors.New("registry: PQ-18 stub, not implemented")

// Load parses the IANA tls-parameters-8.csv export into codepoint-indexed
// entries.
func Load(r io.Reader) (map[uint32]GroupEntry, error) {
	return nil, errNotImplemented
}

// Lookup returns the registry entry for a supported-group codepoint.
func Lookup(m map[uint32]GroupEntry, v uint32) (GroupEntry, bool) {
	return GroupEntry{}, false
}
